// Step 1: Validate Configuration and Inputs
if (qr_input.enable != 0 && qr_input.enable != 1) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_input.body == NULL || qr_input.inertial == NULL || qr_input.weights == NULL) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_input.count < 2 || qr_input.count > 4) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (!isfinite(qr_config.residual_limit_rad) || 
    qr_config.residual_limit_rad < 0.0 || 
    qr_config.residual_limit_rad > ADCS_PI) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_config.required_good < 1 || qr_config.required_good > 20) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_config.allow_outlier_reject != 0 && qr_config.allow_outlier_reject != 1) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}

// Step 2: Handle Disabled State
if (qr_input.enable == 0) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0;
    qr_output.mode = QR_OFF;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    return;
}

// Step 3: Solve with Full Set using QUEST
adcs_status_t status = adcs_quest(
    qr_input.body,
    qr_input.inertial,
    qr_input.weights,
    qr_input.count,
    &qr_output.q_bi
);

if (status != ADCS_OK) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = 0.0;
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}

// Step 4: Compute Worst Angular Residual for Full Set
adcs_mat3_t dcm_full = adcs_quat_to_dcm_bi(&qr_output.q_bi);
double worst_res = -1.0;
int outlier_idx = -1;

for (size_t i = 0; i < qr_input.count; ++i) {
    if (!adcs_is_finite_vec3(&qr_input.body[i]) || !adcs_is_finite_vec3(&qr_input.inertial[i])) {
        qr_state.mode = QR_FAULT;
        qr_output.mode = QR_FAULT;
        qr_output.good = qr_state.good;
        qr_output.worst_residual_rad = 0.0;
        qr_output.used_count = 0;
        qr_output.rejected_outlier = 0;
        return;
    }

    adcs_vec3_t rot_iv = adcs_mat3_mul_vec(&dcm_full, &qr_input.inertial[i]);
    double dot = adcs_vec3_dot(&rot_iv, &qr_input.body[i]);
    double n1 = adcs_vec3_norm(&rot_iv);
    double n2 = adcs_vec3_norm(&qr_input.body[i]);

    double cos_val = dot / (n1 * n2);
    if (cos_val > 1.0) cos_val = 1.0;
    if (cos_val < -1.0) cos_val = -1.0;

    double angle = acos(cos_val);
    if (angle > worst_res) {
        worst_res = angle;
        outlier_idx = (int)i;
    }
}

qr_output.worst_residual_rad = worst_res;
qr_output.used_count = qr_input.count;
qr_output.rejected_outlier = 0;

// Step 5: Outlier Rejection Retry
int need_retry = (worst_res > qr_config.residual_limit_rad) && 
                 (qr_config.allow_outlier_reject == 1) && 
                 (qr_input.count > 2);

if (need_retry) {
    size_t sub_count = qr_input.count - 1;
    const adcs_vec3_t* sub_b[4];
    const adcs_vec3_t* sub_i[4];
    const double* sub_w[4];
    size_t k = 0;

    for (size_t i = 0; i < qr_input.count; ++i) {
        if ((int)i == outlier_idx) continue;
        sub_b[k] = &qr_input.body[i];
        sub_i[k] = &qr_input.inertial[i];
        sub_w[k] = &qr_input.weights[i];
        k++;
    }

    adcs_quat_t q_sub;
    status = adcs_quest(sub_b[0], sub_i[0], sub_w[0], sub_count, &q_sub);

    if (status != ADCS_OK) {
        qr_state.mode = QR_FAULT;
        qr_output.mode = QR_FAULT;
        qr_output.good = qr_state.good;
        qr_output.worst_residual_rad = 0.0;
        qr_output.used_count = 0;
        qr_output.rejected_outlier = 0;
        return;
    }

    adcs_mat3_t dcm_sub = adcs_quat_to_dcm_bi(&q_sub);
    double worst_res_sub = -1.0;

    for (size_t i = 0; i < qr_input.count; ++i) {
        if ((int)i == outlier_idx) continue;

        adcs_vec3_t rot_iv = adcs_mat3_mul_vec(&dcm_sub, &qr_input.inertial[i]);
        double dot = adcs_vec3_dot(&rot_iv, &qr_input.body[i]);
        double n1 = adcs_vec3_norm(&rot_iv);
        double n2 = adcs_vec3_norm(&qr_input.body[i]);

        double cos_val = dot / (n1 * n2);
        if (cos_val > 1.0) cos_val = 1.0;
        if (cos_val < -1.0) cos_val = -1.0;

        double angle = acos(cos_val);
        if (angle > worst_res_sub) {
            worst_res_sub = angle;
        }
    }

    if (worst_res_sub <= qr_config.residual_limit_rad) {
        qr_output.q_bi = q_sub;
        qr_output.worst_residual_rad = worst_res_sub;
        qr_output.used_count = sub_count;
        qr_output.rejected_outlier = 1;
    } else {
        qr_output.worst_residual_rad = worst_res;
        qr_output.used_count = qr_input.count;
        qr_output.rejected_outlier = 0;
    }
}

// Step 6: Update Mode and Good Counter
if (qr_output.worst_residual_rad <= qr_config.residual_limit_rad) {
    qr_state.good++;
    if (qr_state.good >= qr_config.required_good) {
        qr_state.mode = QR_READY;
    } else {
        qr_state.mode = QR_MONITOR;
    }
} else {
    qr_state.good = 0;
    qr_state.mode = QR_MONITOR;
}

qr_output.mode = qr_state.mode;
qr_output.good = qr_state.good;

